use super::*;

/// 🎨️ Indexed authored channels keep their original keys and sample allocations through genuine normal emission, projection and closure.
#[test]
fn original_mesh_tessellation_normal_indexed_channels_preserve_source_rows(){
    use crate::brep::queries::tessellation::tests::observe_tessellation_system as observe;
    use protocol::value::{DslValue,FromValue,retained_clone::{RetainedCloneGrant,RetainedCloneProgress},retirement::controlled::{ControlledRetirement,ErasedControlledRetirement}};
    let law:serde_json::Value=serde_json::from_str(include_str!("../../../🧫️fixtures/🧩️tessellation/🎟️owners.json")).unwrap();let fixture=&law["indexedChannels"];
    for face_uv in[false,true]{for copy in law["copyGrants"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize){
        let(mut job,source)=observe(||{let positions=serde_json::from_value::<Vec<[f32;3]>>(fixture["positions"].clone()).unwrap();let faces=serde_json::from_value::<Vec<Vec<u32>>>(fixture["faces"].clone()).unwrap();let mut mesh=HalfedgeMesh::from_faces(&positions,&faces).unwrap();for row in fixture["attributes"].as_array().unwrap(){let alternate=face_uv&&row["name"]=="uv";let value=serde_json::json!({"domain":if alternate{"face"}else{row["domain"].as_str().unwrap()},"semantic":row["semantic"],"interpolation":if alternate{"constant"}else{row["interpolation"].as_str().unwrap()},"values":if alternate{&fixture["faceUv"]["values"]}else{&row["values"]},"indices":if alternate{&serde_json::Value::Null}else{&row["indices"]}});mesh.set_attribute(row["name"].as_str().unwrap().to_owned(),MeshAttribute::from_value(DslValue::from(value)).unwrap()).unwrap();}MeshTessellationJob::new(mesh)});
        let original_source=job.mesh.vertices.as_ptr();let original_rows=job.mesh.attributes.iter().map(|(key,value)|(key.clone(),key.as_ptr(),value.values.as_ptr())).collect::<Vec<_>>();let(mut born,mut freed,mut turns)=(source.0,source.1,0);
        let output=loop{
            let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:128,maximum_capacity_bytes:job.next_normal_capacity_byte_demand(128).unwrap(),maximum_release_bytes:job.next_normal_release_byte_demand().unwrap(),maximum_depth:job.next_normal_depth_demand().unwrap()};
            for denied in[RetainedCloneGrant {maximum_items:0,..grant},RetainedCloneGrant {maximum_depth:grant.maximum_depth.saturating_sub(1),..grant}]{let progress=job.progress();let((step,receipt),heap)=observe(||job.step(denied).unwrap());assert!(matches!(step,MeshTessellationStep::Working(_)));assert_eq!(receipt,RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(job.progress(),progress);}
            let((step,receipt),heap)=observe(||job.step(grant).unwrap());assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt,job.normal_step_progress());assert!(receipt.fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);assert_eq!(job.mesh.vertices.as_ptr(),original_source);
            if let MeshTessellationStep::Done(output)=step{break output;}
            for(name,key,values)in&original_rows{let row=job.mesh.attributes.get_key_value(name).or_else(||job.output.as_ref().unwrap().attributes.get_key_value(name)).or_else(||job.attribute_pending.as_ref().filter(|(key,_)|key==name).map(|(key,value)|(key,value))).unwrap();assert_eq!(row.0.as_ptr(),*key);assert_eq!(row.1.values.as_ptr(),*values);}
        };
        let read=|name:&str|serde_json::from_value::<Vec<f32>>(fixture[name].clone()).unwrap();assert_eq!(output.normals,read("normals"));assert_eq!(output.colors,read("colors"));let expected=if face_uv{&fixture["faceUv"]}else{fixture};assert_eq!(output.uvs,serde_json::from_value::<Vec<f32>>(expected["uvs"].clone()).unwrap());assert_eq!(output.edge_uvs,serde_json::from_value::<Vec<f32>>(expected["edgeUvs"].clone()).unwrap());assert_eq!(output.edge_is_seam,serde_json::from_value::<Vec<u8>>(fixture["edgeIsSeam"].clone()).unwrap());assert_eq!(output.vertex_ids,serde_json::from_value::<Vec<u32>>(fixture["vertexIds"].clone()).unwrap());assert_eq!(output.edge_ids,serde_json::from_value::<Vec<u32>>(fixture["edgeIds"].clone()).unwrap());
        for row in fixture["attributes"].as_array().unwrap(){let name=row["name"].as_str().unwrap();let(key,value)=output.attributes.get_key_value(name).unwrap();let original=original_rows.iter().find(|(source,_,_)|source==name).unwrap();assert_eq!(key.as_ptr(),original.1);assert_eq!(value.values.as_ptr(),original.2);let expected=if face_uv&&name=="uv"{&fixture["faceUv"]["outputIndices"]}else{&row["outputIndices"]};assert_eq!(value.indices.as_ref().unwrap(),&serde_json::from_value::<Vec<u32>>(expected.clone()).unwrap());}
        let(mut job_owner,heap)=observe(||ControlledRetirement::new(job).unwrap_or_else(|_|panic!("original indexed Job closure unsupported")));assert_eq!(heap,(0,0));let(mut output_owner,heap)=observe(||ControlledRetirement::new(output).unwrap_or_else(|_|panic!("original indexed output closure unsupported")));assert_eq!(heap,(0,0));for owner in[&mut job_owner as&mut dyn ErasedControlledRetirement,&mut output_owner]{while !owner.terminal_is_empty(){let grant=RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:owner.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,heap)=observe(||owner.step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant));born+=heap.0;freed+=heap.1;turns+=1;assert!(turns<100000);}}
        assert_eq!(born,freed);let(_,heap)=observe(||{drop(job_owner);drop(output_owner);});assert_eq!(heap,(0,0));eprintln!("[DEBUG] Original Mesh indexed channels faceUv={face_uv} closeCopy={copy} sameSource=true sameOriginalRows=true actualPhysical={freed} terminalDrop=0");
    }}
}
